// ── Audit Log: CREATE on Employees ──────────────────────────────
// TODO: No audit library found. Install one first:
//   npm install @cap-js/audit-logging   ← preferred (CDS plugin, zero boilerplate)
//   npm install @sap/audit-logging      ← alternative (imperative API)
//
// Until then, use this local wrapper to avoid losing audit events:
const { writeAuditLog } = require('./lib/audit-log-wrapper.js');
await writeAuditLog({
  actor:        req.user?.id ?? 'anonymous',
  action:       'CREATE',
  object:       'Employees',
  objectId:     String(data?.ID ?? req.params?.[0] ?? 'unknown'),
  outcome:      'success',
  tenant:       req.tenant ?? 'default',
  correlationId:
    req.headers?.['x-correlation-id'] ??
    req.headers?.['x-request-id'] ??
    crypto.randomUUID(),
});

// ── Audit Log: DELETE on Employees ──────────────────────────────
const { writeAuditLog } = require('./lib/audit-log-wrapper.js');
await writeAuditLog({
  actor:        req.user?.id ?? 'anonymous',
  action:       'DELETE',
  object:       'Employees',
  objectId:     String(req.params[0] ?? 'unknown'),
  outcome:      'success',
  tenant:       req.tenant ?? 'default',
  correlationId: req.headers?.['x-correlation-id'] ?? crypto.randomUUID(),
});

// ── Audit Log: EXPORT of Employees ──────────────────────────────
const { writeAuditLog } = require('./lib/audit-log-wrapper.js');
await writeAuditLog({
  actor:        req.user?.id ?? 'anonymous',
  action:       'EXPORT',
  object:       'Employees',
  objectId:     'bulk-export',
  outcome:      'success',
  tenant:       req.tenant ?? 'default',
  correlationId: req.headers?.['x-correlation-id'] ?? crypto.randomUUID(),
});
